<?php
require_once __DIR__.'/turnos_service.php';exigirPermissao('turnos');$atual=caixaAtual();$id=(int)($_GET['ver']??($atual['id']??0));$c=null;$res=null;$moves=[];
if($id){$c=query('SELECT s.*,u.nome FROM sessoes_caixa s JOIN usuarios u ON u.id=s.usuario_id WHERE s.id=? AND (?=1 OR s.usuario_id=?)',[$id,admin()?1:0,$_SESSION['user']['id']])->fetch();if(!$c){http_response_code(404);page('Caixa não encontrado');endpage();return;}$res=$c['fechado_em']?json_decode($c['resumo'],true,512,JSON_THROW_ON_ERROR):resumoCaixa($id);$moves=query('SELECT * FROM caixa_movimentos WHERE sessao_id=? ORDER BY id',[$id])->fetchAll();}
$rows=query('SELECT s.*,u.nome FROM sessoes_caixa s JOIN usuarios u ON u.id=s.usuario_id WHERE ?=1 OR s.usuario_id=? ORDER BY s.id DESC LIMIT 100',[admin()?1:0,$_SESSION['user']['id']])->fetchAll();page('Abertura e fechamento de caixa');?>
<section class="card no-print"><p>Um caixa por funcionário, com saldo operacional inicial zero para Pix, cartão e boleto. Recebimentos e reembolsos são conferidos manualmente. Compras de fornecedores não são saídas financeiras deste caixa.</p><?php if(!$atual):?><form method="post"><?php csrf();?><button name="action" value="open_cash">Abrir meu caixa</button></form><?php else:?><p>Seu caixa #<?=$atual['id']?> está aberto desde <?=e($atual['aberto_em'])?>. <a href="index.php?p=vendas">Registrar venda</a></p><?php endif;?></section>
<?php if($c):?><section class="card"><div class="toolbar"><h2>Caixa #<?=$c['id']?> — <?=e($c['nome'])?></h2><button id="print-report" class="secondary" type="button">Imprimir / salvar PDF</button></div><p>Aberto em <?=e($c['aberto_em'])?> · <?=$c['fechado_em']?'Fechado em '.e($c['fechado_em']):'Em andamento'?></p>
<div class="table-wrap"><table><thead><tr><th>Forma</th><th>Recebimentos menos reembolsos</th><?php if($c['fechado_em']):?><th>Conferido</th><th>Diferença</th><?php endif;?></tr></thead><tbody><?php $checked=$c['fechado_em']?json_decode($c['conferido'],true,512,JSON_THROW_ON_ERROR):[];foreach($res['formas'] as $forma=>$n):?><tr><td><?=e($forma)?></td><td><?=money(valorAssinado($n))?></td><?php if($c['fechado_em']):?><td><?=money(valorAssinado($checked[$forma]))?></td><td><?=money(valorAssinado($checked[$forma]-$n))?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div>
<p><b>Recebido líquido: <?=money(valorAssinado($res['recebido_liquido']))?></b> · Vendas líquidas registradas neste caixa: <?=money(decimalValor($res['vendas_liquidas']))?> · Ainda a receber: <?=money(decimalValor($res['a_receber']))?></p><p>O fechamento preserva estes valores. Recebimentos ou devoluções posteriores entram no caixa aberto de quem registrar a operação, sem modificar o fechamento anterior. <?=e($c['observacao'])?></p>
<?php if(!$c['fechado_em']):?><form method="post" class="form-grid no-print"><?php csrf();?><input type="hidden" name="id" value="<?=$c['id']?>"><?php foreach(['pix'=>'Pix','cartao'=>'Cartão de crédito','boleto'=>'Boleto'] as $k=>$label):?><label><?=$label?> líquido conferido (R$)<input name="<?=$k?>" inputmode="decimal" placeholder="0,00" required></label><?php endforeach;?><label>Observação / motivo da diferença<input name="observacao" maxlength="255"></label><div class="form-footer"><button name="action" value="close_cash">Conferir e fechar caixa</button></div></form><?php endif;?>
<h2>Movimentos financeiros</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Venda</th><th>Tipo</th><th>Forma</th><th>Valor</th><th>Referência</th></tr></thead><tbody><?php foreach($moves as $m):?><tr><td><?=e($m['criado_em'])?></td><td>#<?=$m['comprovante_id']?></td><td><?=e($m['tipo'])?></td><td><?=e($m['forma'])?></td><td><?=money($m['valor'])?></td><td><?=e($m['referencia'])?></td></tr><?php endforeach;if(!$moves)emptyRow(6);?></tbody></table></div></section><?php endif;?>
<section class="card no-print"><h2>Últimos 100 caixas</h2><div class="table-wrap"><table><thead><tr><th>Nº</th><th>Funcionário</th><th>Abertura</th><th>Fechamento</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['nome'])?></td><td><?=e($r['aberto_em'])?></td><td><?=e($r['fechado_em']??'Aberto')?></td><td><a href="index.php?p=turnos&ver=<?=$r['id']?>">Conferir</a></td></tr><?php endforeach;if(!$rows)emptyRow(5);?></tbody></table></div></section><?php endpage();
